#!/usr/bin/env python3
"""puerta_comentario.py — PROPUESTA para el ejecutor (NO aplicada). Versión «sin firma».

Puerta común de las tres IA sin servidor ni clave: cada sesión publica un comentario en el
issue «COM3IA solicitudes» del ejecutor y el flujo com3ia-puerta.yml lo evalúa con este
programa. El control de seguridad es la aprobación del propietario en «Review deployments»
(obligatoria en cada corrida) y autorizados.txt (SHA + huella de comite.yml).

Sin red, sin secretos y sin dependencias: lee el JSON del evento issue_comment, decide y
escribe una sola línea «ESTADO|PUERTA|…». Con --salida añade a GITHUB_OUTPUT solo valores
validados con expresiones estrictas; nunca reenvía texto libre del comentario.

Comentarios aceptados (cuerpo exacto; se tolera el pie literal de Claude Code):

    COM3IA-PUERTA-V1
    ```json
    {"tipo":"SOLICITUD","actor":"CLAUDE_A","sha":"<40 hex>","caso":"SYN-RP-20261101-A"}
    ```

  · SOLICITUD → DESPACHAR una prueba de AISLAMIENTO (nunca modelos). El SHA debe figurar en
    autorizados.txt junto a la huella vigente de comite.yml. Identificador de la solicitud
    derivado del comentario (RQ-C<id>), único por comentario.
  · {"tipo":"ACUSE","actor":"…","nonce":"<32 hex>"} → ACUSE: prueba que esa sesión llega a la
    puerta. No despacha nada.
  · {"tipo":"CIERRE","solicitud_id":"RQ-…","sha":"<40 hex>"} → CIERRE: solo lectura.

El autor debe ser el propietario (login, tipo User y author_association OWNER). Las tres IA
publican con la cuenta del propietario: «actor» es una declaración, no una autenticación.
"""
import argparse
import json
import pathlib
import re
import sys

CABECERA = "COM3IA-PUERTA-V1"
PIE_CLAUDE = "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_"
IAS = ("CLAUDE_A", "CLAUDE_B", "CHATGPT")
CASO = "SYN-RP-20261101-A"
MAX_CUERPO = 8192
CUERPO = re.compile(r"COM3IA-PUERTA-V1\n```json\n(\{[^\n]{2,2000}\})\n```\Z")
ID = re.compile(r"RQ-[A-Z0-9]{10,26}\Z")
SHA = re.compile(r"[0-9a-f]{40}\Z")
HEX32 = re.compile(r"[0-9a-f]{32}\Z")
HEX64 = re.compile(r"[0-9a-f]{64}\Z")


class Rechazo(Exception):
    pass


def _unicos(pares):
    d = {}
    for k, v in pares:
        if k in d:
            raise Rechazo("DUPLICADO")
        d[k] = v
    return d


def _json(texto):
    def malo(_):
        raise Rechazo("FORMATO")
    try:
        return json.loads(texto, object_pairs_hook=_unicos, parse_constant=malo)
    except (ValueError, RecursionError):
        raise Rechazo("FORMATO") from None


def _texto(v, patron):
    return isinstance(v, str) and patron.fullmatch(v) is not None


def autorizado(autorizados, sha, huella):
    """¿Hay una línea «<sha> <huella>» en autorizados.txt? Igual criterio que comite.yml."""
    for linea in (autorizados or "").splitlines():
        partes = linea.split()
        if len(partes) >= 2 and partes[0] == sha and partes[1] == huella:
            return True
    return False


def evaluar(evento, titulo_issue, dueno, huella, autorizados):
    """Devuelve (decision, valores): IGNORAR, DESPACHAR, ACUSE o CIERRE.
    Lanza Rechazo(motivo) si el comentario es para la puerta pero no es válido."""
    if not isinstance(evento, dict) or evento.get("action") != "created":
        return "IGNORAR", {}
    iss, com = evento.get("issue") or {}, evento.get("comment") or {}
    if iss.get("title") != titulo_issue or "pull_request" in iss:
        return "IGNORAR", {}
    cuerpo = com.get("body")
    if not isinstance(cuerpo, str) or not cuerpo.startswith(CABECERA):
        return "IGNORAR", {}
    usuario = com.get("user") or {}
    if (not isinstance(usuario.get("login"), str) or usuario["login"].lower() != dueno.lower()
            or usuario.get("type") != "User" or com.get("author_association") != "OWNER"):
        raise Rechazo("AUTOR")
    if len(cuerpo.encode("utf-8")) > MAX_CUERPO:
        raise Rechazo("TAMANO")
    t = cuerpo.rstrip(" \t\r\n")
    if t.endswith(PIE_CLAUDE):
        t = t[:-len(PIE_CLAUDE)]
    m = CUERPO.fullmatch(t)
    if not m:
        raise Rechazo("FORMATO")
    datos = _json(m.group(1))
    if not isinstance(datos, dict):
        raise Rechazo("FORMATO")
    tipo = datos.get("tipo")

    if tipo == "ACUSE":
        if set(datos) != {"tipo", "actor", "nonce"} or datos["actor"] not in IAS or not _texto(datos["nonce"], HEX32):
            raise Rechazo("ACUSE")
        return "ACUSE", {"actor": datos["actor"], "nonce": datos["nonce"]}

    if tipo == "CIERRE":
        if (set(datos) != {"tipo", "solicitud_id", "sha"} or not _texto(datos["solicitud_id"], ID)
                or not _texto(datos["sha"], SHA)):
            raise Rechazo("CIERRE")
        return "CIERRE", {"solicitud_id": datos["solicitud_id"], "sha": datos["sha"]}

    if tipo != "SOLICITUD" or set(datos) != {"tipo", "actor", "sha", "caso"}:
        raise Rechazo("TIPO")
    if datos["actor"] not in IAS or not _texto(datos["sha"], SHA) or datos["caso"] != CASO:
        raise Rechazo("SOLICITUD")
    if not _texto(huella, HEX64):
        raise Rechazo("HUELLA")
    if not autorizado(autorizados, datos["sha"], huella):
        raise Rechazo("SHA_NO_AUTORIZADO")
    cid = com.get("id")
    if type(cid) is not int or not 0 < cid < 10 ** 15:
        raise Rechazo("COMENTARIO_ID")
    return "DESPACHAR", {"solicitud_id": "RQ-C%015d" % cid, "actor": datos["actor"], "sha": datos["sha"],
                         "caso": CASO, "tope": "3", "modo": "aislamiento"}


def main(argv=None):
    ap = argparse.ArgumentParser(description="Puerta COM3IA por comentario, sin firma (sin red ni secretos)")
    ap.add_argument("--evento", required=True)
    ap.add_argument("--titulo", required=True)
    ap.add_argument("--dueno", required=True)
    ap.add_argument("--huella", required=True)
    ap.add_argument("--autorizados", required=True)
    ap.add_argument("--salida")
    a = ap.parse_args(argv)
    try:
        p, q = pathlib.Path(a.evento), pathlib.Path(a.autorizados)
        for f in (p, q):
            if f.is_symlink() or not f.is_file() or f.stat().st_size > 1024 * 1024:
                raise Rechazo("EVENTO")
        evento = json.loads(p.read_text(encoding="utf-8"))
        decision, valores = evaluar(evento, a.titulo, a.dueno, a.huella, q.read_text(encoding="utf-8"))
    except Rechazo as e:
        decision, valores = "RECHAZO", {"motivo": str(e)}
    except (ValueError, OSError):
        decision, valores = "RECHAZO", {"motivo": "EVENTO"}
    print("ESTADO|PUERTA|" + decision + ("|" + valores["motivo"] if decision == "RECHAZO" else ""))
    if a.salida:
        with open(a.salida, "a", encoding="ascii") as f:
            f.write("decision=" + decision + "\n")
            for k, v in valores.items():
                if "\n" in v or "\r" in v:
                    raise SystemExit(70)
                f.write(k + "=" + v + "\n")
    return 0 if decision != "RECHAZO" else 64


if __name__ == "__main__":
    sys.exit(main())
